// Signs one request per item (callers may pass many items, e.g. lead batches).
const crypto = require('crypto');
const base = $env.KLYRO_API_BASE || 'http://127.0.0.1:4100/api/v1';
const secret = $env.KLYRO_HMAC_SECRET;
if (!secret) throw new Error('KLYRO_HMAC_SECRET is not set in the n8n environment');
const item = $input.item.json;
if (!item.path) throw new Error('Klyro API call is missing "path"');
const method = (item.method || 'POST').toUpperCase();
const body = item.body || {};
const raw = JSON.stringify(body);
const ts = Date.now().toString();
const signature = crypto.createHmac('sha256', secret).update(ts + '.' + raw).digest('hex');
const idem = item.idempotencyKey || crypto.randomUUID();
return { json: { url: base + item.path, method, raw, ts, signature, idem } };
